function bindDutyPrepaymentObservers(){if(!dutyPrepaymentReady)return;const orderDialog=$('#orderDialog'),detailDialog=$('#detail');if(orderDialog)new MutationObserver(()=>{const form=orderDialog.querySelector('#orderForm');if(!form||form.querySelector('[name="duty_prepaid"]'))return;const editing=form.querySelector('h2')?.textContent?.includes('编辑'),o=editing?detailOrder():null,anchor=form.querySelector('[name="requirements"]')?.closest('label');if(!anchor)return;const selectLabel=document.createElement('label');selectLabel.className='duty-prepaid-field';selectLabel.innerHTML=`关税预付 *<select name="duty_prepaid" required><option value="false" ${o?.duty_prepaid===true?'':'selected'}>否</option><option value="true" ${o?.duty_prepaid===true?'selected':''}>是</option></select>`;const noteLabel=document.createElement('label');noteLabel.className='wide duty-prepaid-note-field';noteLabel.innerHTML=`关税预付备注<textarea name="duty_prepaid_note" maxlength="2000" placeholder="填写预付金额、付款时间或其他关税说明">${esc(o?.duty_prepaid_note||'')}</textarea>`;anchor.before(selectLabel,noteLabel)}).observe(orderDialog,{childList:true,subtree:true});if(detailDialog)new MutationObserver(()=>{const o=detailOrder(),list=detailDialog.querySelector('.detail dl');if(!o||!Object.prototype.hasOwnProperty.call(o,'duty_prepaid')||!list||list.querySelector('.duty-prepaid-detail'))return;const status=document.createElement('div');status.className='duty-prepaid-detail';status.innerHTML=`<dt>关税预付</dt><dd><strong class="${o.duty_prepaid?'prepaid':'not-prepaid'}">${o.duty_prepaid?'是':'否'}</strong></dd>`;const note=document.createElement('div');note.className='duty-prepaid-note-detail';note.innerHTML=`<dt>关税预付备注</dt><dd>${esc(o.duty_prepaid_note||'-')}</dd>`;list.append(status,note)}).observe(detailDialog,{childList:true,subtree:true})}
